import{_ as e,o as r,c as a,a5 as n}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse(`{"title":"Glossary of Terms and Methods","description":"Define the guide's core vocabulary, evidence standards, tool entry points, and reading paths so ideas can transfer between chapters.","frontmatter":{"title":"Glossary of Terms and Methods","description":"Define the guide's core vocabulary, evidence standards, tool entry points, and reading paths so ideas can transfer between chapters.","updated":"2026-09-07T00:00:00.000Z"},"headers":[],"relativePath":"en/reference/glossary.md","filePath":"en/reference/glossary.md","lastUpdated":1788739200000}`),d={name:"en/reference/glossary.md"};function o(i,t,s,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="glossary-of-terms-and-methods" tabindex="-1">Glossary of Terms and Methods <a class="header-anchor" href="#glossary-of-terms-and-methods" aria-label="Permalink to &quot;Glossary of Terms and Methods&quot;">​</a></h1><p>This is not an attempt to turn life into a vocabulary test. It gives recurring words in <em>Life Level-up Guide</em> a stable place to land. Return here when a term is unclear or you do not know which page to open next.</p><h2 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h2><p>Find the task you are facing, then follow “definition → evidence → next step”. If a term does not help you complete a task, preserve a sample, or make a better decision, you do not need to memorise it for its own sake.</p><h2 id="problems-and-goals" tabindex="-1">Problems and Goals <a class="header-anchor" href="#problems-and-goals" aria-label="Permalink to &quot;Problems and Goals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this guide</th><th>Continue here</th></tr></thead><tbody><tr><td><strong>Real problem</strong></td><td>A situation with affected people and an action to complete, not “I want to improve”</td><td><a href="./../threads/part-1/1-understanding">Learning Principles</a></td></tr><tr><td><strong>Context</strong></td><td>When, where, and for whom a skill will be used</td><td><a href="./../threads/part-1/0-cefr">CEFR Goals and Self-check</a></td></tr><tr><td><strong>Acceptance standard</strong></td><td>An outcome another person can observe, check, or restate</td><td><a href="./../templates/ai-task-brief">AI Task Brief</a></td></tr><tr><td><strong>Evaluation set</strong></td><td>Normal, boundary, missing/conflicting, and realistic redacted samples used to check output instead of showing only model-friendly examples</td><td><a href="./../templates/ai-task-brief">AI Task Brief</a></td></tr><tr><td><strong>Main question</strong></td><td>One answerable question tracked for a week</td><td><a href="./../threads/part-5/90-day-plan">90-Day Action Plan</a></td></tr></tbody></table><h2 id="evidence-and-judgment" tabindex="-1">Evidence and Judgment <a class="header-anchor" href="#evidence-and-judgment" aria-label="Permalink to &quot;Evidence and Judgment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this guide</th><th>Common trap</th></tr></thead><tbody><tr><td><strong>Baseline</strong></td><td>A raw sample saved before tool support or concentrated training</td><td>Replacing the first version with feelings or a polished result</td></tr><tr><td><strong>Evidence</strong></td><td>A record that returns to work, recording, test, source, or real feedback</td><td>Treating hours, saves, or chat logs as proof of ability</td></tr><tr><td><strong>Fact</strong></td><td>Something with a source, date, sample, or direct observation</td><td>Writing an explanation as a proven cause</td></tr><tr><td><strong>Interpretation</strong></td><td>A reading of the facts that may still need revision</td><td>Stopping verification because it sounds plausible</td></tr><tr><td><strong>Hypothesis</strong></td><td>A judgment waiting for the next action to test it</td><td>Writing a wish or model answer as a conclusion</td></tr><tr><td><strong>Inference boundary</strong></td><td>Separating what a source says, what evidence supports, and what you add</td><td>Treating a headline, emotion, or one anecdote as the whole picture</td></tr><tr><td><strong>Narrative compression</strong></td><td>Turning a complex experience into a shareable sentence or causal chain</td><td>Mistaking a shortened story for the whole event after removing chance, others&#39; work, and unknowns</td></tr><tr><td><strong>Hindsight bias</strong></td><td>Explaining a past choice with outcomes that were known only later</td><td>Sending later information backwards into the past</td></tr></tbody></table><h2 id="learning-actions" tabindex="-1">Learning Actions <a class="header-anchor" href="#learning-actions" aria-label="Permalink to &quot;Learning Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this guide</th><th>Related chapter</th></tr></thead><tbody><tr><td><strong>Retrieval practice</strong></td><td>Close the source and answer, retell, write, or perform from memory</td><td><a href="./../threads/part-1/1-understanding">Learning Principles</a></td></tr><tr><td><strong>Complete learning loop</strong></td><td>Define the task, preserve a first version, diagnose, target input, produce actively, and record feedback/state</td><td><a href="./../threads/part-1/1-understanding">Learning Principles</a></td></tr><tr><td><strong>First-version conditions</strong></td><td>Material, time, tools, help, and acceptance standard recorded for the first attempt so later comparison is not confused by polish</td><td><a href="./../templates/english-diagnostic">English Diagnostic</a></td></tr><tr><td><strong>Capacity mode</strong></td><td>Choose a full, downgraded, minimum, or paused version of an action based on attention, body, time, and responsibility</td><td><a href="./../threads/part-4/daily-system">Daily System</a></td></tr><tr><td><strong>Distributed practice</strong></td><td>Return at multiple points instead of cramming once</td><td><a href="./../threads/part-1/2-vocabulary">Vocabulary</a></td></tr><tr><td><strong>Unknown-item decision queue</strong></td><td>Decide whether to skip, infer, look up, learn, or professionally verify each unknown and record why</td><td><a href="./../templates/vocabulary-audit">Vocabulary Evidence Card</a></td></tr><tr><td><strong>Eight vocabulary dimensions</strong></td><td>Separate form, sound, current sense, collocation, grammar, register, concept boundary, and retrieval condition</td><td><a href="./../threads/part-1/2-vocabulary">Vocabulary</a></td></tr><tr><td><strong>Receptive / productive vocabulary</strong></td><td>Receptive knowledge understands in listening/reading; productive knowledge retrieves in speaking/writing without the answer displayed</td><td><a href="./../threads/part-1/2-vocabulary">Vocabulary</a></td></tr><tr><td><strong>Form–meaning choice</strong></td><td>Treat grammar as a choice that changes time, participants, condition, negation scope, logic, or certainty rather than only a rule label</td><td><a href="./../threads/part-1/grammar">Grammar</a></td></tr><tr><td><strong>Grammar contrast card</strong></td><td>Preserve an original sentence, likely interpretation, intended meaning, form contrast, revision reason, and delayed retest for one real task</td><td><a href="./../templates/grammar-evidence">Grammar Evidence Card</a></td></tr><tr><td><strong>Reference variety</strong></td><td>A relatively stable dictionary-audio, spelling, or pronunciation reference chosen to reduce early decisions; it does not rank other English varieties below it</td><td><a href="./../threads/part-1/5-speaking">Speaking</a></td></tr><tr><td><strong>Intelligibility / comprehensibility</strong></td><td>The first records how much meaning the listener recovered; the second records effort such as guessing, replay, or confirmation. Both differ from accentedness</td><td><a href="./../threads/part-1/5-speaking">Speaking</a></td></tr><tr><td><strong>Listener retelling</strong></td><td>A listener restates gist, detail, numbers, responsibility, and next step without seeing the script, showing what the sound actually carried</td><td><a href="./../templates/speaking-evidence">Speaking Evidence Card</a></td></tr><tr><td><strong>First-pass baseline</strong></td><td>Preserve original gist, detail, timestamps, and action judgment after the first play under recorded caption, pause, speed, device, and environment conditions</td><td><a href="./../templates/listening-audit">Listening Evidence Card</a></td></tr><tr><td><strong>Scaffold ladder</strong></td><td>Adjustable support moving from a no-caption first pass through local replay, English transcript, and minimum background help, then closing text and removing support after a delay</td><td><a href="./../threads/part-1/3-listening">Listening</a></td></tr><tr><td><strong>Meaning reconstruction</strong></td><td>Recover gist, relationships, critical detail, and next step in a retelling, process, decision, or handover instead of repeating the model word for word</td><td><a href="./../threads/part-1/3-listening">Listening</a></td></tr><tr><td><strong>First-reading baseline</strong></td><td>Preserve original gist, structure, unknowns, and action judgment after the first read under recorded time, dictionary, translation, search, and AI conditions</td><td><a href="./../templates/reading-evidence">Reading Evidence Card</a></td></tr><tr><td><strong>Claim map</strong></td><td>Label paragraphs as background, problem, claim, reason, evidence, limit, or action while preserving source locations</td><td><a href="./../threads/part-1/4-reading">Reading</a></td></tr><tr><td><strong>Technical fact card</strong></td><td>Keep documentation goal, version, prerequisites, minimum input, expected/actual output, failure, and next test on one page</td><td><a href="./../templates/reading-evidence">Reading Evidence Card</a></td></tr><tr><td><strong>Narrow reading</strong></td><td>Read multiple sources in one topic or domain so background, terminology, and structure recur</td><td><a href="./../threads/part-1/4-reading">Reading</a></td></tr><tr><td><strong>Fact and responsibility ledger</strong></td><td>Record source, version, permission, confidence, and owner for facts, numbers, quotations, experience, inference, and information about others</td><td><a href="./../threads/part-1/6-writing">Writing</a></td></tr><tr><td><strong>Feedback uptake</strong></td><td>Accept, partly accept, reject, or defer each item with a reason, then test independent use in a parallel text</td><td><a href="./../templates/writing-evidence">Writing Evidence Card</a></td></tr><tr><td><strong>Decision to sign</strong></td><td>Decide before delivery whether the text is accountable as written, needs verification, needs narrower scope, or should not be published</td><td><a href="./../templates/writing-evidence">Writing Evidence Card</a></td></tr><tr><td><strong>Intensive listening/reading</strong></td><td>Use short material to check detail, structure, evidence, and language form</td><td><a href="./../threads/part-1/3-listening">Listening</a> · <a href="./../threads/part-1/4-reading">Reading</a></td></tr><tr><td><strong>Parallel material</strong></td><td>A different source with similar difficulty and task for testing transfer</td><td><a href="./../templates/reading-evidence">Reading Evidence Card</a></td></tr><tr><td><strong>Transfer</strong></td><td>Complete a related action after changing topic, listener, time, or task</td><td><a href="./../templates/90-day-cycle">90-Day Cycle Map</a></td></tr><tr><td><strong>Delayed retention</strong></td><td>Complete a similar task after time has passed and recent prompts are removed</td><td><a href="./../threads/part-3/5-evidence-and-transfer">Evidence</a></td></tr><tr><td><strong>Evidence chain</strong></td><td>One page connecting baseline, immediate performance, delayed retention, transfer, and next step</td><td><a href="./../templates/evidence-chain">Evidence Chain Template</a> · <a href="./../threads/part-3/5-evidence-and-transfer">Evidence</a></td></tr><tr><td><strong>Variation</strong></td><td>Keep the core action while changing the topic, listener, time, or constraint to test whether learning is real</td><td><a href="./../threads/part-4/rhythm-and-compounding">Rhythm</a></td></tr><tr><td><strong>Learner agency</strong></td><td>The learner participates in defining the goal, submits an own first version, states capacity, questions feedback, and carries responsibility appropriate to age and context</td><td><a href="./../threads/part-4/family-learning">Family Learning</a></td></tr><tr><td><strong>Role language map</strong></td><td>Extract recruiter communication, project explanation, technical follow-up, asynchronous writing, and other language tasks from one real role and connect them to existing evidence</td><td><a href="./../threads/part-1/8-job-search-english">Job-search English</a></td></tr></tbody></table><h2 id="tools-and-delivery" tabindex="-1">Tools and Delivery <a class="header-anchor" href="#tools-and-delivery" aria-label="Permalink to &quot;Tools and Delivery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this guide</th><th>Related chapter</th></tr></thead><tbody><tr><td><strong>Task brief</strong></td><td>A one-page record of context, input, action, boundaries, acceptance, and ownership</td><td><a href="./../templates/ai-task-brief">AI Task Brief</a></td></tr><tr><td><strong>Learning State file</strong></td><td>A versioned source of truth outside any conversation, preserving goal, evidence, errors, boundaries, handover, and next task</td><td><a href="./../templates/learning-state">Learning State</a> · <a href="./../templates/toolkit-walkthrough">Toolkit Walkthrough</a></td></tr><tr><td><strong>Case review</strong></td><td>A record that separates a public experience into source, facts, judgment, outcome, and transferable principle</td><td><a href="./../templates/ai-case-review">AI Case Review</a></td></tr><tr><td><strong>Evidence card</strong></td><td>A template for preserving a first take, feedback, and retest for one language skill</td><td><a href="./../threads/part-0/prologue">Four-skill path</a></td></tr><tr><td><strong>Reader Field Note</strong></td><td>A private-first two-pass record of reading entry, real action, immediate result, delayed retest, transfer, and editorial feedback</td><td><a href="./../templates/reader-field-note">Reader Field Note</a></td></tr><tr><td><strong>Family Learning Agreement</strong></td><td>A private worksheet where learner and guardian record goals, concerns, support, AI and data boundaries separately, then review fourteen days of evidence together</td><td><a href="./../templates/family-learning-agreement">Family Learning Agreement</a></td></tr><tr><td><strong>Job-search English Evidence Card</strong></td><td>One record connecting a real role, unscripted baseline, stories, unfamiliar follow-ups, asynchronous writing, delayed retest, and integrity boundaries</td><td><a href="./../templates/interview-evidence">Job-search English Evidence Card</a></td></tr><tr><td><strong>Grammar Evidence Card</strong></td><td>Track one high-impact structure through a real-task baseline, meaning contrast, four-skill retrieval, feedback classification, and day-fourteen transfer</td><td><a href="./../templates/grammar-evidence">Grammar Evidence Card</a></td></tr><tr><td><strong>Listening Evidence Card</strong></td><td>Connect material conditions, a no-caption first pass, six-layer error map, caption scaffolds, meaning reconstruction, action output, and parallel-material transfer</td><td><a href="./../templates/listening-audit">Listening Evidence Card</a></td></tr><tr><td><strong>Reading Evidence Card</strong></td><td>Connect source version, first pass, six-layer barrier map, claims/evidence, technical facts, source comparison, real output, and delayed transfer</td><td><a href="./../templates/reading-evidence">Reading Evidence Card</a></td></tr><tr><td><strong>Writing Evidence Card</strong></td><td>Connect real audience, unaided draft, fact sources, translation changes, five revision passes, feedback uptake, AI use, async delivery, and authorship responsibility</td><td><a href="./../templates/writing-evidence">Writing Evidence Card</a></td></tr><tr><td><strong>Vocabulary Evidence Card</strong></td><td>Connect a real task, first encounter, unknown-item decisions, eight-dimensional verification, unaided retrieval, error repair, and delayed transfer</td><td><a href="./../templates/vocabulary-audit">Vocabulary Evidence Card</a></td></tr><tr><td><strong>Speaking Evidence Card</strong></td><td>A private record connecting reference variety, three unscripted baselines, listener retelling, comprehension effort, interaction repair, unfamiliar follow-ups, and delayed transfer</td><td><a href="./../templates/speaking-evidence">Speaking Evidence Card</a></td></tr><tr><td><strong>Interaction repair</strong></td><td>When hearing, scope, or knowledge is incomplete, request repetition, confirm, ask for thinking time, and summarise agreement</td><td><a href="./../threads/part-1/5-speaking">Speaking</a> · <a href="./../threads/part-1/8-job-search-english">Job-search English</a></td></tr><tr><td><strong>Artifact</strong></td><td>An output others can read, use, question, or improve; not necessarily a product</td><td><a href="./../threads/part-3/4-artifacts-and-delivery">Artifacts</a></td></tr><tr><td><strong>Delivery</strong></td><td>Completing work under a real audience, user, or constraint and accepting the result</td><td><a href="./../threads/part-5/90-day-plan">90-Day Action Plan</a></td></tr><tr><td><strong>Human gate</strong></td><td>AI may assist, but named people confirm source, fact, permission, privacy, quality, cost, and final ownership before release or execution</td><td><a href="./../templates/ai-task-brief">AI Task Brief</a> · <a href="./../threads/part-3/2-ai-development-and-resource-layer">AI Project Development</a></td></tr><tr><td><strong>Speed debt</strong></td><td>Real cost owed when shorter immediate time creates more rework, verification, communication, or incident risk</td><td><a href="./../templates/ai-learning-log">AI Learning Log</a></td></tr><tr><td><strong>AI Learning Log</strong></td><td>A private sheet comparing unaided, assisted, delayed-independent, and parallel tasks to record tool contribution and owned ability</td><td><a href="./../templates/ai-learning-log">AI Learning Log</a></td></tr><tr><td><strong>Rollback</strong></td><td>Pause, degrade, switch, or return to a known usable state after failure</td><td><a href="./../threads/part-3/1-ai-learning">AI Learning and Project Practice</a></td></tr></tbody></table><h2 id="life-and-boundaries" tabindex="-1">Life and Boundaries <a class="header-anchor" href="#life-and-boundaries" aria-label="Permalink to &quot;Life and Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this guide</th><th>Related chapter</th></tr></thead><tbody><tr><td><strong>Boundary</strong></td><td>What I will do to protect myself and state a consequence when something happens</td><td><a href="./../threads/part-2/relationships">Relationships</a></td></tr><tr><td><strong>Recovery</strong></td><td>Restore safety, body, relationships, and agency before efficiency and growth</td><td><a href="./../threads/part-2/recovery">Recovery</a></td></tr><tr><td><strong>Recovery mode</strong></td><td>A safety, reduced-load, or rebuilding load chosen from current safety, basic care, and agency; a life-recording term rather than a clinical rating</td><td><a href="./../threads/part-2/recovery">Recovery</a></td></tr><tr><td><strong>Return-to-work load test</strong></td><td>Increase one variable such as duration, complexity, responsibility, or exposure, then inspect same-day completion and next-day cost</td><td><a href="./../threads/part-2/recovery">Recovery</a></td></tr><tr><td><strong>Support agreement</strong></td><td>State what a supporter may do, must not replace, when to escalate, and how control returns as risk falls</td><td><a href="./../threads/part-2/recovery">Recovery</a> · <a href="./../templates/life-practice-toolkit">Life Practice Toolkit</a></td></tr><tr><td><strong>Minimum order</strong></td><td>A safe action and visible result that remain repeatable during disorder</td><td><a href="./../templates/life-practice-toolkit">Life Practice Toolkit</a></td></tr><tr><td><strong>Minimum viable day</strong></td><td>A version of the day that preserves safety, one minimum output, and a cue for the next step at the capacity available</td><td><a href="./../threads/part-4/daily-system">Daily System</a></td></tr><tr><td><strong>Capacity budget</strong></td><td>A rough estimate that includes time, attention, body, and responsibility rather than time alone</td><td><a href="./../threads/part-4/daily-system">Daily System</a></td></tr><tr><td><strong>Return action</strong></td><td>The smallest output that can be completed within 24 hours and bring the system back after interruption</td><td><a href="./../threads/part-4/daily-system">Daily System</a></td></tr><tr><td><strong>Rhythm</strong></td><td>One pattern of action that remains recognisable and executable at different capacities, connecting repetition, feedback, and recovery over time</td><td><a href="./../threads/part-4/rhythm-and-compounding">Rhythm</a></td></tr><tr><td><strong>Compounding</strong></td><td>Today&#39;s choice reduces tomorrow&#39;s hesitation, rework, or recovery cost, allowing ability, trust, judgment, and recovery to support one another</td><td><a href="./../threads/part-4/rhythm-and-compounding">Rhythm</a></td></tr><tr><td><strong>Minimum contract</strong></td><td>An agreement for bad days that states when to downgrade, what action to keep, and when to ask for help or escalate risk</td><td><a href="./../threads/part-4/rhythm-and-compounding">Rhythm</a></td></tr><tr><td><strong>Rhythm ledger</strong></td><td>One page each week recording the main question, protected action, useful feedback, repeated resistance, and next condition to change</td><td><a href="./../templates/rhythm-ledger">Rhythm Ledger Template</a> · <a href="./../threads/part-4/rhythm-and-compounding">Rhythm</a></td></tr><tr><td><strong>Cost</strong></td><td>Time, money, health, relationships, privacy, and responsibility that must be named</td><td><a href="./../threads/part-2/decision">Decision-Making</a></td></tr><tr><td><strong>Reversibility</strong></td><td>Whether a choice can be paused, undone, or changed back at manageable cost</td><td><a href="./../threads/part-2/decision">Decision-Making</a></td></tr><tr><td><strong>Value conflict</strong></td><td>Two important aims cannot both be fully preserved, requiring an explicit priority and a statement of what each option gives up</td><td><a href="./../threads/part-2/decision">Decision-Making</a></td></tr><tr><td><strong>Decision authority</strong></td><td>Final power to approve or refuse a choice, with the source of authority, affected people, and responsibility made explicit</td><td><a href="./../threads/part-2/decision">Decision-Making</a></td></tr><tr><td><strong>Disconfirming evidence</strong></td><td>A fact or result named before action that would remove support for the current choice, guarding against collecting only confirmation</td><td><a href="./../threads/part-2/decision">Decision-Making</a></td></tr><tr><td><strong>Stop gate</strong></td><td>An observable evidence, cost, safety, or responsibility signal that triggers pause, stop, rollback, or escalation for help</td><td><a href="./../threads/part-2/decision">Decision-Making</a> · <a href="./../templates/life-practice-toolkit">Life Practice Toolkit</a></td></tr></tbody></table><h2 id="one-sentence-to-keep" tabindex="-1">One Sentence to Keep <a class="header-anchor" href="#one-sentence-to-keep" aria-label="Permalink to &quot;One Sentence to Keep&quot;">​</a></h2><p>If you keep one sequence: name the problem, save a baseline, use the right tool for one small task, let a real person test it, write the feedback into the next action, and recover before adding pressure.</p><p>Related entry points: <a href="./../threads/part-0/prologue">Prologue: Do Not Rush to Change Your Life</a> | <a href="./../templates/90-day-cycle">90-Day Cycle Map</a></p>',17)])])}const m=e(d,[["render",o]]);export{p as __pageData,m as default};
